const sqlite3 = require('sqlite3').verbose();
const path = require('path');

const db = new sqlite3.Database(path.join(__dirname, 'incidents.db'));

// Wrapper to mimic better-sqlite3 API with promises
db.prepare = (sql) => {
  return {
    run: (...params) => new Promise((resolve, reject) => {
      db.run(sql, params, function(err) {
        if (err) reject(err);
        else resolve({ lastID: this.lastID, changes: this.changes });
      });
    }),
    get: (...params) => new Promise((resolve, reject) => {
      db.get(sql, params, (err, row) => {
        if (err) reject(err);
        else resolve(row);
      });
    }),
    all: (...params) => new Promise((resolve, reject) => {
      db.all(sql, params, (err, rows) => {
        if (err) reject(err);
        else resolve(rows);
      });
    })
  };
};

const originalExec = db.exec.bind(db);
db.exec = (sql) => new Promise((resolve, reject) => {
  originalExec(sql, (err) => {
    if (err) reject(err);
    else resolve();
  });
});

// Initialize database
(async () => {
  try {
    await db.exec(`
      CREATE TABLE IF NOT EXISTS incidents (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        description TEXT,
        severity TEXT NOT NULL DEFAULT 'LOW',
        status TEXT NOT NULL DEFAULT 'OPEN',
        service_name TEXT,
        assigned_to TEXT DEFAULT '',
        resolution TEXT DEFAULT '',
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS notification_confirmations (
        id TEXT PRIMARY KEY,
        incident_id TEXT NOT NULL,
        channel TEXT NOT NULL,
        confirmed_at TEXT NOT NULL
      );
    `);
  } catch (err) {
    console.error('[Incident] Erreur init DB:', err);
  }
})();

module.exports = db;
